#pragma once
// The official Krunker client's sound-name array (client/src/net/krunker_sounds.c, generated by
// tools/krunker/extract_sounds.py from the live game.deob.js): the "s" PLAYER_SOUND / "so"
// PLAY_SOUND / "sso" STOP_SOUND packets carry a sound as an index into it (game.playerSound:
// `isAsset || !isFinite(i) ? i : sounds[i]`). The names are assets/sound/<name>.mp3.

// The name at index, NULL past the table.
const char *krunker_sound_name(int index);
int krunker_sound_count(void);
